using GameLauncherGUI;
using System.Reflection;

internal static class ExperienceChecks
{
    private static int checks;
    private static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;}
    private static void Reject(Action action,string message){try{action();}catch(Exception ex)when(ex is IOException or ArgumentException or OperationCanceledException){checks++;return;}throw new Exception(message);}
    private static GameInfo Game(string name,string path,string id="")=>new(){Name=name,ExePath=path,SteamAppId=id};
    internal static void Run(bool ui)
    {
        string root=Path.Combine(Path.GetTempPath(),"PlaySpaceExperience-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        var a=Game("CS",Path.Combine(root,"a.exe"),"730");var b=Game("Other",Path.Combine(root,"b.exe"),"730");var c=Game("CS",Path.Combine(root,"c.exe"));var d=Game("Alias",a.ExePath.ToUpperInvariant());
        var groups=LibraryDuplicates.Find(new[]{a,b,c,d});Check(groups.Count==1&&groups[0].Games.Length==3,"Transitive duplicates or title-only exclusion failed");
        Check(LibraryDuplicates.Find(new[]{Game("A",""),Game("B","")}).Count==0,"Empty paths merged");
        Check(LibraryDuplicates.Find(new[]{Game("A",a.ExePath,"10"),Game("Alias",a.ExePath),Game("B",a.ExePath,"20")}).All(g=>g.Games.Where(x=>!string.IsNullOrEmpty(x.SteamAppId)).Select(x=>x.SteamAppId).Distinct().Count()<=1),"Different AppIDs merged through shared launcher");
        var argumentA=Game("A",a.ExePath);var argumentB=Game("B",a.ExePath);argumentB.LaunchArguments="--another-game";Check(LibraryDuplicates.Find(new[]{argumentA,argumentB}).Count==0,"Different launch arguments merged");
        a.PlayedSeconds=100;b.PlayedSeconds=150;b.IsPinned=true;b.LastLaunchUtc=DateTimeOffset.UtcNow;
        var merged=LibraryDuplicates.Merge(a,new[]{a,b});Check(merged.PlayedSeconds==150&&merged.IsPinned&&merged.LastLaunchUtc==b.LastLaunchUtc,"Stats should merge by maximum, not sum");Check(!a.IsPinned&&a.PlayedSeconds==100,"Merge mutated source before save");
        a.SteamPlaytimeUser="first";a.SteamPlaytimeMinutes=10;b.SteamPlaytimeUser="second";b.SteamPlaytimeMinutes=999;
        Check(LibraryDuplicates.Merge(a,new[]{b}).SteamPlaytimeMinutes==10,"Steam users mixed");
        var collections=new LibraryCollections(root);collections.Create("Кооп");collections.Set(b.LibraryId,"Кооп",true);collections.MergeMembership(a.LibraryId,new[]{a.LibraryId,b.LibraryId});Check(new LibraryCollections(root).Contains(a,"Кооп"),"Collection membership lost");
        a.IsPinned=true;a.PlayedSeconds=36000;
        var ranked=PersonalRecommendations.Rank(new[]{a},Array.Empty<string>());Check(ranked.All(r=>r.Game.Id!="730"),"Personal feed includes owned game");Check(ranked[0].Score>0&&ranked[0].Reason.Contains("жанр"),"Personal reasons missing");Check(PersonalRecommendations.Rank(Array.Empty<GameInfo>(),Array.Empty<string>()).All(r=>r.Score==0&&r.Reason.Contains("мало")),"Cold start falsely personalized");
        var pref=new LauncherPreferences{HomeBanner=false,HomeLibrary="Закреплённые",HomePosters=true,HomeSort=3,PersonalRecommendations=false,HighContrast=true};pref.Save(root);var loaded=LauncherPreferences.Load(root);Check(!loaded.HomeBanner&&loaded.HomePosters&&loaded.HomeSort==3&&!loaded.PersonalRecommendations&&loaded.HighContrast,"Home settings did not persist");
        var package=new ModPackage{Owner="Author",Name="Fixture"};var version=new ModVersion{Version="1.2.3",DownloadUrl="https://example.invalid/mod.zip",FileSize=1024,Dependencies=new[]{"Author-Dependency-1.0.0"}};
        string planText=ModInstallPlanForm.Describe(root,new[]{new ModSelection(package,version)});Check(planText.Contains(version.DownloadUrl)&&planText.Contains("Author-Dependency")&&planText.Contains("1.2.3"),"Mod plan provenance/dependencies missing");
        version.FileSize=0;Check(ModInstallPlanForm.Describe(root,new[]{new ModSelection(package,version)}).Contains("размер не указан"),"Unknown size was presented as zero");
        string nativeGame=Path.Combine(root,"Native");Directory.CreateDirectory(nativeGame);var native=Game("RimWorld",Path.Combine(nativeGame,"game.exe"),"294100");native.InstallDirectory=nativeGame;string zip=Path.Combine(root,"mod.zip");using(var archive=System.IO.Compression.ZipFile.Open(zip,System.IO.Compression.ZipArchiveMode.Create)){using var writer=new StreamWriter(archive.CreateEntry("Sample/About/About.xml").Open());writer.Write("fixture");}string nativePreview=NativeModImport.DescribeArchive(NativeModAdapter.For(native)!,native,zip);Check(nativePreview.Contains("About.xml")&&nativePreview.Contains("не подтверждены"),"Local ZIP preview hides files or claims verified provenance");
        var profileRoot=Path.Combine(root,"Profiles");Directory.CreateDirectory(profileRoot);var profiles=new ModProfileStore(profileRoot,()=>{});var saved=profiles.Save("Кооп");Check(profiles.Preview(saved.Id).Contains("Переключаются только"),"Profile scope missing from preview");Check(profiles.Preview(null).Contains("Будут отключены"),"Vanilla profile preview missing");
        string source=Path.Combine(root,"Original"),target=Path.Combine(root,"Moved");Directory.CreateDirectory(Path.Combine(source,"Empty"));File.WriteAllText(Path.Combine(source,"game.exe"),"fixture-executable");File.WriteAllText(Path.Combine(source,"data.bin"),"fixture-data");
        File.WriteAllText(Path.Combine(source,"game.exe:Zone.Identifier"),"[ZoneTransfer]\r\nZoneId=3\r\n");
        var sourceProfiles=new ModProfileStore(source,()=>{});sourceProfiles.Save("Оригинальный набор");var nativeRoot=Path.Combine(source,"Mods");Directory.CreateDirectory(nativeRoot);new ModProfileStore(nativeRoot,()=>{}).Save("Нативный набор");
        var plan=GameTransfer.Preview(source,target,default);Check(plan.Bytes>0&&plan.Directories!.Contains("Empty"),"Transfer manifest/empty dirs missing");
        Reject(()=>GameTransfer.Preview(source,source,default),"Same path accepted");Reject(()=>GameTransfer.Preview(source,Path.Combine(source,"Nested"),default),"Nested path accepted");Reject(()=>GameTransfer.Preview(Path.GetPathRoot(source)!,target,default),"Drive root accepted");
        string journalFile=Path.Combine(root,"transfer.json");int closed=0;var journal=GameTransfer.Execute(plan,journalFile,()=>closed++,default);Check(closed>=2,"Running-process guard was not rechecked");Check(Directory.Exists(journal.Backup)&&Directory.Exists(target),"Backup or target missing");Check(Directory.Exists(Path.Combine(target,"Empty")),"Empty game directories not copied");Check((File.GetAttributes(source)&FileAttributes.ReparsePoint)!=0&&File.ReadAllText(Path.Combine(source,"data.bin"))=="fixture-data","Old path does not resolve through junction");
        Check(new ModProfileStore(target,()=>{}).List().Count==1,"Root-bound profile not migrated");Check(new ModProfileStore(Path.Combine(target,"Mods"),()=>{}).List().Count==1,"Nested native profile not migrated");
        Check(File.ReadAllText(Path.Combine(target,"game.exe:Zone.Identifier")).Contains("ZoneId=3"),"Transfer stripped internet-zone metadata");
        File.WriteAllText(Path.Combine(target,"data.bin"),"changed");Reject(()=>GameTransfer.ReleaseBackup(journal,journalFile,()=>{},default),"Corrupt destination allowed backup deletion");Check(Directory.Exists(journal.Backup),"Backup lost after failed validation");File.WriteAllText(Path.Combine(target,"data.bin"),"fixture-data");
        GameTransfer.Restore(journal,journalFile,()=>{});Check(Directory.Exists(source)&&(File.GetAttributes(source)&FileAttributes.ReparsePoint)==0&&Directory.Exists(target),"Restore lost original or new copy");Check(new ModProfileStore(source,()=>{}).List().Count==1,"Original profile lost during restore");
        string destination2=Path.Combine(root,"MovedAgain");var plan2=GameTransfer.Preview(source,destination2,default);var j2=GameTransfer.Execute(plan2,journalFile,()=>{},default);File.WriteAllText(Path.Combine(destination2,"new-log.txt"),"new");GameTransfer.ReleaseBackup(j2,journalFile,()=>{},default);Check(!Directory.Exists(j2.Backup)&&Directory.Exists(source)&&File.Exists(Path.Combine(destination2,"new-log.txt")),"Cleanup removed destination or rejected added log");
        Reject(()=>GameTransfer.Restore(j2 with{Phase="Завершено"},journalFile,()=>{}),"Restore after cleanup accepted");Directory.Delete(source); // remove only fixture junction
        string failSource=Path.Combine(root,"LinkFailure"),failTarget=Path.Combine(root,"LinkFailureTarget");Directory.CreateDirectory(failSource);File.WriteAllText(Path.Combine(failSource,"game.exe"),"fixture");
        var failPlan=GameTransfer.Preview(failSource,failTarget,default);Reject(()=>GameTransfer.Execute(failPlan,Path.Combine(root,"failed.json"),()=>{},default,link:(s,t)=>throw new IOException("fixture link failure")),"Link failure not propagated");Check(Directory.Exists(failSource)&&File.Exists(Path.Combine(failSource,"game.exe")),"Link failure did not restore source");
        var cancelled=new CancellationToken(true);Reject(()=>GameTransfer.Preview(failSource,Path.Combine(root,"Cancelled"),cancelled),"Cancellation ignored");
        if(ui)
        {
            using(var main=new Form1(root,false)){var hero=(Control)typeof(Form1).GetField("hero",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(main)!;Check(((TableLayoutPanel)hero.Parent!).RowStyles[0].Height==0,"Home banner not collapsed");var list=(CustomCheckListBox)typeof(Form1).GetField("listBoxGames",BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(main)!;Check(list.PosterView,"Home poster preference not applied");}
            using var grid=new CustomCheckListBox{Size=new(700,400),ShowPinButtons=true,ShowProfileButtons=true};for(int i=0;i<20;i++)grid.Items.Add(new("Game "+i,false,"description"));grid.CreateControl();grid.Navigate(Keys.End);Check(grid.SelectedIndex==19,"Keyboard End failed");grid.Navigate(Keys.Home);Check(grid.SelectedIndex==0,"Keyboard Home failed");grid.Navigate(Keys.PageDown);Check(grid.SelectedIndex>0,"Keyboard PageDown failed");
            var accessible=grid.AccessibilityObject;Check(accessible.Role==AccessibleRole.List&&accessible.GetChildCount()==20,"Accessible list missing");Check(accessible.GetChild(2)!.Name=="Game 2"&&accessible.GetChild(2)!.Description=="description","Accessible game metadata missing");accessible.GetChild(2)!.DoDefaultAction();Check(grid.SelectedIndex==2,"Accessible selection failed");int pin=-1;grid.PinToggleRequested+=i=>pin=i;grid.Navigate(Keys.Control|Keys.D);Check(pin==2,"Keyboard pin failed");
            using var description=new FormattedDescription{Text="Доступное описание"};Check(description.AccessibilityObject.Role==AccessibleRole.Text&&description.AccessibilityObject.Value==description.Text,"Screen reader cannot read description");
            using var form=new HomeSettingsForm(root,()=>{});using var mods=new ModInstallPlanForm(root,new[]{new ModSelection(package,version)});using var duplicateForm=new DuplicateGamesForm(()=>groups,(g,k)=>{});using var transferForm=new GameTransferForm(Game("Пример игры",Path.Combine(failSource,"game.exe")),root);
            string screenshots=Path.GetFullPath("artifacts/feature-pack-previews");Directory.CreateDirectory(screenshots);
            int shot=0;foreach(var window in new Form[]{form,mods,duplicateForm,transferForm}){window.Show();Application.DoEvents();UiTypography.Apply(window);PresentationOptions.Apply(window);UiLayout.Apply(window);UiLayout.Fit(window);using var image=new Bitmap(window.Width,window.Height);window.DrawToBitmap(image,window.ClientRectangle);image.Save(Path.Combine(screenshots,(++shot)+".png"));window.Close();checks++;}
        }
        PresentationOptions.Configure(new());Console.WriteLine($"PASS: {checks} experience checks: deduplication, collection preservation, personal recommendations, mod previews, home settings, verified transfer/junction/rollback/cleanup and accessibility. Temporary fixtures only: {root}");
    }
}
